BEGIN;
SET search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('eeeeeeee-0000-4000-8000-000000000001','limits-owner@test.local',now()),('eeeeeeee-0000-4000-8000-000000000002','limits-buyer@test.local',now());
SELECT set_config('request.jwt.claims','{"sub":"eeeeeeee-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
CREATE TEMP TABLE f AS SELECT public.create_property('Limits apartment','Description','Cotroceni','Private address','apartment',50,2,1,2019,10000000,50000,'{}') j;
CREATE TEMP TABLE a AS SELECT public.start_auction((SELECT id FROM app.listings WHERE property_id=(SELECT (j->>'id')::uuid FROM f) AND transaction_type='rent'),'sealed','public',now()-interval '1 second',now()+interval '1 hour',NULL,100) j;
SELECT throws_ok('SELECT app.require_staff()','P0001','Staff MFA required','ordinary owner has no staff powers');
UPDATE app.profiles SET is_staff=true WHERE id=auth.uid();
SELECT throws_ok('SELECT app.require_staff()','P0001','Staff MFA required','staff requires aal2');
SELECT set_config('request.jwt.claims','{"sub":"eeeeeeee-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
SELECT lives_ok('SELECT app.require_staff()','staff aal2 allowed');
SELECT set_config('request.jwt.claims','{"sub":"eeeeeeee-0000-4000-8000-000000000002"}',true);
INSERT INTO app.bids(auction_id,bidder_id,amount_minor,idempotency_key) SELECT (SELECT (j->>'id')::uuid FROM a),auth.uid(),1000,gen_random_uuid() FROM generate_series(1,30);
SELECT throws_ok(format('SELECT public.place_bid(%L,1000,gen_random_uuid())',(SELECT j->>'id' FROM a)),'P0001','Bid rate limit exceeded','bid limit enforced');
INSERT INTO app.viewings(listing_id,owner_id,buyer_id,requested_at,message) SELECT (SELECT id FROM app.listings WHERE auction_id=(SELECT (j->>'id')::uuid FROM a)),'eeeeeeee-0000-4000-8000-000000000001',auth.uid(),now()+interval '1 day','fixture' FROM generate_series(1,10);
SELECT throws_ok(format('SELECT public.request_viewing(%L,now()+interval ''1 day'','''')',(SELECT id FROM app.listings WHERE auction_id=(SELECT (j->>'id')::uuid FROM a))),'P0001','Viewing rate limit exceeded','viewing limit enforced');
SELECT public.send_message((SELECT id FROM app.listings WHERE auction_id=(SELECT (j->>'id')::uuid FROM a)),'Hello',NULL);
INSERT INTO app.messages(conversation_id,sender_id,body) SELECT (SELECT id FROM app.conversations WHERE buyer_id=auth.uid()),auth.uid(),'fixture' FROM generate_series(1,19);
SELECT throws_ok(format('SELECT public.send_message(%L,''Hello'',NULL)',(SELECT id FROM app.listings WHERE auction_id=(SELECT (j->>'id')::uuid FROM a))),'P0001','Message rate limit exceeded','message limit enforced');
SELECT ok(NOT has_function_privilege('anon','public.place_bid(uuid,bigint,uuid)','EXECUTE'),'anonymous bid RPC inaccessible');
SELECT ok(NOT has_function_privilege('authenticated','public.close_expired_auctions()','EXECUTE'),'worker inaccessible to client');
SELECT is((SELECT count(*)::integer FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='app' AND c.relkind='r' AND NOT c.relrowsecurity),0,'every core table has RLS');
SELECT * FROM finish();
ROLLBACK;
